"use client";

import * as React from "react";
import { PnLBadge } from "@/components/moneytrees/pnl-badge";
import { TickerChart, type TickerPoint } from "@/components/moneytrees/ticker-chart";
import { LiquidSurface } from "@/components/moneytrees/liquid-surface";
import { cn } from "@/lib/utils";

type Props = {
  symbol: string;
  name?: string;
  price: number;
  change24h?: number;
  changePercent24h?: number;
  spark?: TickerPoint[];
  hot?: boolean;
  className?: string;
  onClick?: () => void;
  /** Inline action(s) rendered bottom-right; clicks don't trigger `onClick`. */
  actions?: React.ReactNode;
};

/**
 * Bubbly ticker card. Wraps content in a `LiquidSurface` so the surface
 * inherits the active rendering tier (native canvas, polyfilled, or CSS).
 * The `hot` flag adds the gold glow shadow on top of the bubble shadow stack.
 */
export function TickerCard({
  symbol,
  name,
  price,
  change24h,
  changePercent24h,
  spark,
  hot,
  className,
  onClick,
  actions,
}: Props) {
  const formatted =
    price >= 1
      ? `$${price.toLocaleString(undefined, { maximumFractionDigits: 2 })}`
      : `$${price.toPrecision(4)}`;

  // Flash the price element on live updates: bull wash on up, bear on down.
  const prevPrice = React.useRef(price);
  const [flash, setFlash] = React.useState<"up" | "down" | null>(null);
  React.useEffect(() => {
    if (price === prevPrice.current) return;
    setFlash(price > prevPrice.current ? "up" : "down");
    prevPrice.current = price;
    const id = window.setTimeout(() => setFlash(null), 1300);
    return () => window.clearTimeout(id);
  }, [price]);

  return (
    <LiquidSurface
      variant="card"
      interactive
      onClick={onClick}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
      onKeyDown={
        onClick
          ? (e: React.KeyboardEvent) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onClick();
              }
            }
          : undefined
      }
      className={cn("relative cursor-pointer p-card text-card-foreground", hot && "mt-hot", className)}
    >
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <div className="font-mono text-sm font-semibold leading-none">${symbol}</div>
          {name && <div className="mt-1 truncate text-xs text-muted-foreground">{name}</div>}
        </div>
        <div className="text-right">
          <div
            className={cn(
              "font-mono text-sm tabular-nums",
              flash === "up" && "mt-price-up",
              flash === "down" && "mt-price-down",
            )}
          >
            {formatted}
          </div>
          {change24h !== undefined && (
            <PnLBadge
              value={change24h}
              percent={changePercent24h}
              size="sm"
              className="mt-1"
              showSign={false}
            />
          )}
        </div>
      </div>
      {spark && spark.length > 0 && (
        <div className="mt-3">
          <TickerChart data={spark} variant="sparkline" height={36} />
        </div>
      )}
      {actions && (
        <div
          className="absolute bottom-2 left-2"
          onClick={(e) => e.stopPropagation()}
          onKeyDown={(e) => e.stopPropagation()}
        >
          {actions}
        </div>
      )}
    </LiquidSurface>
  );
}
